/**
 * Geo Tracker - Minimal Client Script
 * 
 * Size: ~500 bytes gzipped
 * Purpose: Optional client-side tracking for humans with JavaScript
 * 
 * Usage: <script src="https://yourdomain.com/tracker.min.js?p=PROJECT_ID"></script>
 * 
 * Note: Bots are tracked server-side via proxy, no user code needed!
 */

(function() {
  'use strict';

  // Get project ID from script src
  const script = document.currentScript;
  if (!script) return;

  const params = new URLSearchParams(script.src.split('?')[1] || '');
  const projectId = params.get('p');
  if (!projectId) return;

  // Get base URL from script origin
  const baseUrl = new URL(script.src).origin;
  const endpoint = baseUrl + '/api/tracking/capture';

  // Build minimal payload
  const payload = {
    projectId,
    eventType: 'page_view',
    path: window.location.pathname,
    url: window.location.href,
    title: document.title,
    userAgent: navigator.userAgent,
    referrer: document.referrer || undefined,
  };

  // Send via sendBeacon (most reliable)
  if (navigator.sendBeacon) {
    navigator.sendBeacon(endpoint, JSON.stringify(payload));
  } else {
    // Fallback to fetch
    fetch(endpoint, {
      method: 'POST',
      body: JSON.stringify(payload),
      keepalive: true,
    }).catch(() => {});
  }
})();

